    16	public class App {
    17	    private static final ObjectMapper MAPPER = new ObjectMapper();
    18	
    19	    private final ReservationService reservations;
    20	    private final ReportService reports;
    21	
    22	    public App(ReservationService reservations, ReportService reports) {
    23	        this.reservations = reservations;
    24	        this.reports = reports;
    25	    }
    26	
    27	    public Javalin create() {
    28	        Javalin app = Javalin.create(config -> config.showJavalinBanner = false);
    29	
    30	        app.get("/rooms", ctx -> json(ctx, 200, Rooms.ALL.stream().map(Json::room).toList()));
    31	
    32	        app.post("/reservations", ctx -> json(ctx, 201,
    33	                Json.reservation(reservations.create(RequestParser.newReservation(MAPPER, ctx.body())))));
    34	        app.get("/reservations/{id}", ctx -> reservation(ctx, reservations::get));
    35	        app.post("/reservations/{id}/confirmation", ctx -> reservation(ctx, reservations::confirm));
    36	        app.post("/reservations/{id}/cancellation", ctx -> reservation(ctx, reservations::cancel));
    37	        app.post("/reservations/{id}/check-in", ctx -> reservation(ctx, reservations::checkIn));
    38	        app.post("/reservations/{id}/check-out", ctx -> json(ctx, 200, Json.receipt(reservations.checkOut(id(ctx)))));
    39	        app.get("/reservations/{id}/document", ctx -> json(ctx, 200, Json.receipt(reservations.document(id(ctx)))));
    40	
    41	        app.get("/messages", ctx -> json(ctx, 200, reservations.messages().stream().map(Json::message).toList()));
    42	
    43	        app.get("/reports/occupancy", ctx -> csv(ctx,
    44	                reports.occupancy(RequestParser.date(ctx.queryParam("date"), "date"))));
    45	        app.get("/reports/revenue", ctx -> csv(ctx,
    46	                reports.revenue(RequestParser.month(ctx.queryParam("month")))));
    47	
    48	        app.exception(DomainException.class, (e, ctx) ->
    49	                json(ctx, e.code().httpStatus(), Json.error(e.code().name(), e.getMessage())));
    50	        app.exception(Exception.class, (e, ctx) -> {
    51	            e.printStackTrace();
    52	            json(ctx, 500, Json.error("INTERNAL_ERROR", "Erro interno"));
    53	        });
    54	        return app;
    55	    }
    56	
    57	    private void reservation(Context ctx, Function<Long, br.com.marealta.domain.Reservation> action) {
    58	        json(ctx, 200, Json.reservation(action.apply(id(ctx))));
    59	    }
    60	
    61	    /** Id que não é número não pode existir. */
    62	    private static long id(Context ctx) {
    63	        String raw = ctx.pathParam("id");
    64	        try {
    65	            return Long.parseLong(raw);
    66	        } catch (NumberFormatException e) {
    67	            throw new DomainException(Code.RESERVATION_NOT_FOUND, "Reserva não encontrada: " + raw);
    68	        }
    69	    }
    70	
    71	    private static void json(Context ctx, int status, Object body) {
    72	        try {
    73	            ctx.status(status).contentType("application/json").result(MAPPER.writeValueAsString(body));
    74	        } catch (JsonProcessingException e) {
    75	            throw new IllegalStateException(e);
    76	        }
    77	    }
    78	
    79	    private static void csv(Context ctx, String body) {
    80	        ctx.status(200).contentType("text/csv; charset=utf-8").result(body);
    81	    }
    82	}
