     1	package br.com.marealta.http;
     2	
     3	import java.time.LocalDate;
     4	import java.time.YearMonth;
     5	import java.time.format.DateTimeParseException;
     6	
     7	import com.fasterxml.jackson.core.JsonProcessingException;
     8	import com.fasterxml.jackson.databind.JsonNode;
     9	import com.fasterxml.jackson.databind.ObjectMapper;
    10	
    11	import br.com.marealta.domain.DomainException;
    12	import br.com.marealta.service.NewReservation;
    13	
    14	/** Converte o que chega pelo HTTP em valores do domínio, recusando o que está malformado. */
    15	final class RequestParser {
    16	    private RequestParser() {
    17	    }
    18	
    19	    static NewReservation newReservation(ObjectMapper mapper, String body) {
    20	        JsonNode json;
    21	        try {
    22	            json = mapper.readTree(body);
    23	        } catch (JsonProcessingException e) {
    24	            throw DomainException.invalid("O corpo não é um JSON válido");
    25	        }
    26	        if (json == null || !json.isObject()) {
    27	            throw DomainException.invalid("O corpo deve ser um objeto JSON");
    28	        }
    29	        JsonNode company = json.get("companyCode");
    30	        return new NewReservation(
    31	                integer(json, "roomNumber"),
    32	                text(json, "guestName"),
    33	                text(json, "guestEmail"),
    34	                text(json, "guestCpf"),
    35	                date(text(json, "checkIn"), "checkIn"),
    36	                date(text(json, "checkOut"), "checkOut"),
    37	                integer(json, "guests"),
    38	                text(json, "ratePlan"),
    39	                company != null && company.isTextual() ? company.asText() : null);
    40	    }
    41	
    42	    static LocalDate date(String value, String field) {
    43	        try {
    44	            return LocalDate.parse(value);
    45	        } catch (DateTimeParseException | NullPointerException e) {
    46	            throw DomainException.invalid("Data inválida em " + field + " (use AAAA-MM-DD)");
    47	        }
    48	    }
    49	
    50	    static YearMonth month(String value) {
    51	        try {
    52	            return YearMonth.parse(value);
    53	        } catch (DateTimeParseException | NullPointerException e) {
    54	            throw DomainException.invalid("Mês inválido (use AAAA-MM)");
    55	        }
    56	    }
    57	
    58	    private static String text(JsonNode json, String field) {
    59	        JsonNode node = json.get(field);
    60	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
    61	            throw DomainException.invalid("Campo obrigatório ausente ou inválido: " + field);
    62	        }
    63	        return node.asText();
    64	    }
    65	
    66	    private static int integer(JsonNode json, String field) {
    67	        JsonNode node = json.get(field);
    68	        if (node == null || !node.isIntegralNumber() || !node.canConvertToInt()) {
    69	            throw DomainException.invalid("Campo obrigatório ausente ou inválido: " + field);
    70	        }
    71	        return node.asInt();
    72	    }
    73	}
