     8	import br.com.marealta.domain.Money;
     9	import br.com.marealta.domain.Reservation;
    10	import br.com.marealta.domain.Room;
    11	import br.com.marealta.domain.Rooms;
    12	import br.com.marealta.persistence.Database;
    13	import br.com.marealta.persistence.ReservationRepository;
    14	
    15	public class ReportService {
    16	    private final Database database;
    17	    private final ReservationRepository reservations = new ReservationRepository();
    18	
    19	    public ReportService(Database database) {
    20	        this.database = database;
    21	    }
    22	
    23	    public String occupancy(LocalDate night) {
    24	        List<Reservation> occupying = database.tx(connection -> reservations.findPaidOccupying(connection, night));
    25	        StringBuilder csv = new StringBuilder("room,type,reservation,check_in,check_out\n");
    26	        for (Reservation reservation : occupying) {
    27	            Room room = Rooms.find(reservation.roomNumber()).orElseThrow();
    28	            csv.append(String.join(",", String.valueOf(room.number()), room.type().name(),
    29	                    String.valueOf(reservation.id()), reservation.checkIn().toString(),
    30	                    reservation.checkOut().toString())).append('\n');
    31	        }
    32	        csv.append("total,").append(occupying.size()).append('/').append(Rooms.ALL.size()).append('\n');
    33	        return csv.toString();
    34	    }
    35	
    36	    public String revenue(YearMonth month) {
    37	        List<Reservation> kept = database.tx(connection ->
    38	                reservations.findWithRevenueStartingBetween(connection, month.atDay(1), month.plusMonths(1).atDay(1)));
    39	        StringBuilder csv = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    40	        BigDecimal total = Money.ZERO;
    41	        for (Reservation reservation : kept) {
    42	            BigDecimal amount = reservation.amountPaid().subtract(
    43	                    reservation.refund() == null ? Money.ZERO : reservation.refund());
    44	            total = total.add(amount);
    45	            csv.append(String.join(",", String.valueOf(reservation.id()), String.valueOf(reservation.roomNumber()),
    46	                    reservation.checkIn().toString(), reservation.checkOut().toString(),
    47	                    reservation.status().name(), amount.toPlainString())).append('\n');
    48	        }
    49	        csv.append("total,").append(total.toPlainString()).append('\n');
    50	        return csv.toString();
    51	    }
    52	}
