     1	package br.com.marealta.service;
     2	
     3	import java.util.List;
     4	
     5	import br.com.marealta.domain.DomainException;
     6	import br.com.marealta.domain.DomainException.Code;
     7	import br.com.marealta.domain.Message;
     8	import br.com.marealta.domain.Money;
     9	import br.com.marealta.domain.Quote;
    10	import br.com.marealta.domain.Receipt;
    11	import br.com.marealta.domain.Reservation;
    12	import br.com.marealta.domain.ReservationStatus;
    13	import br.com.marealta.domain.Room;
    14	import br.com.marealta.domain.Rooms;
    15	import br.com.marealta.domain.Stay;
    16	import br.com.marealta.persistence.Database;
    17	import br.com.marealta.persistence.MessageRepository;
    18	import br.com.marealta.persistence.ReservationRepository;
    19	import br.com.marealta.plan.RatePlan;
    20	import br.com.marealta.plan.RatePlans;
    21	
    22	public class ReservationService {
    23	    private final Database database;
    24	    private final ReservationRepository reservations = new ReservationRepository();
    25	    private final MessageRepository messages = new MessageRepository();
    26	
    27	    public ReservationService(Database database) {
    28	        this.database = database;
    29	    }
    30	
    31	    public Reservation create(NewReservation request) {
    32	        if (!request.checkOut().isAfter(request.checkIn())) {
    33	            throw DomainException.invalid("A saída deve ser depois da entrada");
    34	        }
    35	        if (request.guests() < 1) {
    36	            throw DomainException.invalid("A reserva precisa de pelo menos um hóspede");
    37	        }
    38	        RatePlan plan = RatePlans.find(request.ratePlan());
    39	        if (plan == null) {
    40	            throw DomainException.invalid("Plano de tarifa desconhecido: " + request.ratePlan());
    41	        }
    42	        Room room = room(request.roomNumber());
    43	        if (request.guests() > room.capacity()) {
    44	            throw new DomainException(Code.CAPACITY_EXCEEDED,
    45	                    "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " hóspedes");
    46	        }
    47	        Stay stay = new Stay(room, request.checkIn(), request.checkOut(), request.companyCode());
    48	        plan.validate(stay);
    49	        Quote quote = plan.quote(stay);
    50	
    51	        return database.tx(connection -> {
    52	            reservations.lockRoom(connection, room.number());
    53	            if (reservations.hasActiveReservation(connection, room.number(), request.checkIn(), request.checkOut())) {
    54	                throw new DomainException(Code.ROOM_UNAVAILABLE, "O quarto já está reservado em alguma das noites");
    55	            }
    56	            String companyCode = "CORPORATE".equals(plan.code()) ? request.companyCode() : null;
    57	            Reservation draft = new Reservation(0, room.number(), request.guestName(), request.guestEmail(),
    58	                    request.guestCpf(), request.checkIn(), request.checkOut(), request.guests(), plan.code(),
    59	                    companyCode, stay.nights(), quote.subtotal(), quote.discount(), ReservationStatus.PENDING,
    60	                    Money.ZERO, null);
    61	            return reservations.insert(connection, draft);
    62	        });
    63	    }
    64	
    65	    public Reservation get(long id) {
    66	        return database.tx(connection -> load(connection, id, false));
    67	    }
    68	
    69	    public Reservation confirm(long id) {
    70	        return database.tx(connection -> {
    71	            Reservation reservation = load(connection, id, true);
    72	            reservation.confirm();
    73	            reservations.update(connection, reservation);
    74	            messages.insert(connection, Message.reservationConfirmed(reservation, receipt(reservation)));
    75	            return reservation;
    76	        });
    77	    }
    78	
    79	    public Reservation cancel(long id) {
    80	        return database.tx(connection -> {
    81	            Reservation reservation = load(connection, id, true);
    82	            reservation.cancel(RatePlans.find(reservation.ratePlan())::refund);
    83	            reservations.update(connection, reservation);
    84	            return reservation;
    85	        });
    86	    }
    87	
    88	    public Reservation checkIn(long id) {
    89	        return database.tx(connection -> {
    90	            Reservation reservation = load(connection, id, true);
    91	            reservation.registerCheckIn();
    92	            reservations.update(connection, reservation);
    93	            return reservation;
    94	        });
    95	    }
    96	
    97	    public Receipt checkOut(long id) {
    98	        return database.tx(connection -> {
    99	            Reservation reservation = load(connection, id, true);
   100	            reservation.registerCheckOut();
   101	            reservations.update(connection, reservation);
   102	            return receipt(reservation);
   103	        });
   104	    }
   105	
   106	    /** Segunda via do comprovante: só existe para reserva paga. */
   107	    public Receipt document(long id) {
   108	        Reservation reservation = get(id);
   109	        if (!reservation.status().isPaid()) {
   110	            throw new DomainException(Code.OPERATION_NOT_ALLOWED,
   111	                    "Só há comprovante para reserva paga (status " + reservation.status() + ")");
   112	        }
   113	        return receipt(reservation);
   114	    }
   115	
   116	    public List<Message> messages() {
   117	        return database.tx(messages::findAll);
   118	    }
   119	
   120	    private Reservation load(java.sql.Connection connection, long id, boolean forUpdate) throws java.sql.SQLException {
   121	        return reservations.find(connection, id, forUpdate)
   122	                .orElseThrow(() -> new DomainException(Code.RESERVATION_NOT_FOUND, "Reserva não encontrada: " + id));
   123	    }
   124	
   125	    private static Room room(int number) {
   126	        return Rooms.find(number)
   127	                .orElseThrow(() -> new DomainException(Code.ROOM_NOT_FOUND, "Quarto não encontrado: " + number));
   128	    }
   129	
   130	    private static Receipt receipt(Reservation reservation) {
   131	        return Receipt.of(reservation, room(reservation.roomNumber()));
   132	    }
   133	}

