    17	        BigDecimal subtotal = Money.ZERO;
    18	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    19	            subtotal = subtotal.add(nightPrice(night));
    20	        }
    21	        return subtotal;
    22	    }
