    10	public class Database {
    11	    /** Trabalho feito dentro de uma transação. */
    12	    public interface Work<T> {
    13	        T run(Connection connection) throws SQLException;
    14	    }
    15	
    16	    private static final String SCHEMA = """
    17	            CREATE TABLE IF NOT EXISTS reservations (
    18	                id           BIGSERIAL PRIMARY KEY,
    19	                room_number  INT NOT NULL,
    20	                guest_name   TEXT NOT NULL,
    21	                guest_email  TEXT NOT NULL,
    22	                guest_cpf    TEXT NOT NULL,
    23	                check_in     DATE NOT NULL,
    24	                check_out    DATE NOT NULL,
    25	                guests       INT NOT NULL,
    26	                rate_plan    TEXT NOT NULL,
    27	                company_code TEXT,
    28	                nights       INT NOT NULL,
    29	                subtotal     NUMERIC(12,2) NOT NULL,
    30	                discount     NUMERIC(12,2) NOT NULL,
    31	                status       TEXT NOT NULL,
    32	                amount_paid  NUMERIC(12,2) NOT NULL,
    33	                refund       NUMERIC(12,2)
    34	            );
    35	            CREATE INDEX IF NOT EXISTS reservations_room_idx ON reservations (room_number, check_in, check_out);
    36	            CREATE TABLE IF NOT EXISTS messages (
    37	                id      BIGSERIAL PRIMARY KEY,
    38	                channel TEXT NOT NULL,
    39	                to_addr TEXT NOT NULL,
    40	                subject TEXT NOT NULL,
    41	                body    TEXT NOT NULL
    42	            );
    43	            """;
    44	
    45	    private final HikariDataSource dataSource;
    46	
    47	    public Database(String url, String user, String password) {
    48	        HikariConfig config = new HikariConfig();
    49	        config.setJdbcUrl(url);
    50	        config.setUsername(user);
    51	        config.setPassword(password);
    52	        config.setInitializationFailTimeout(60_000);
    53	        this.dataSource = new HikariDataSource(config);
    54	    }
    55	
    56	    public void createSchema() {
    57	        tx(connection -> {
    58	            try (Statement statement = connection.createStatement()) {
    59	                // Evita corrida entre duas instâncias subindo juntas.
    60	                statement.execute("SELECT pg_advisory_xact_lock(7070)");
    61	                statement.execute(SCHEMA);
    62	            }
    63	            return null;
    64	        });
    65	    }
    66	
    67	    public <T> T tx(Work<T> work) {
    68	        try (Connection connection = dataSource.getConnection()) {
    69	            connection.setAutoCommit(false);
    70	            try {
    71	                T result = work.run(connection);
    72	                connection.commit();
    73	                return result;
    74	            } catch (Throwable e) {
    75	                connection.rollback();
    76	                throw e;
    77	            }
    78	        } catch (SQLException e) {
    79	            throw new IllegalStateException("Erro de banco de dados", e);
    80	        }
    81	    }
    82	}
