    21	    /** Serializa as reservas de um mesmo quarto até o fim da transação. */
    22	    public void lockRoom(Connection connection, int roomNumber) throws SQLException {
    23	        try (PreparedStatement statement = connection.prepareStatement("SELECT pg_advisory_xact_lock(?)")) {
    24	            statement.setLong(1, roomNumber);
    25	            statement.execute();
    26	        }
    27	    }
    28	
    29	    public boolean hasActiveReservation(Connection connection, int roomNumber, LocalDate checkIn, LocalDate checkOut)
    30	            throws SQLException {
    31	        String sql = "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
    32	                + "AND check_in < ? AND check_out > ? LIMIT 1";
    33	        try (PreparedStatement statement = connection.prepareStatement(sql)) {
    34	            statement.setInt(1, roomNumber);
    35	            statement.setObject(2, checkOut);
    36	            statement.setObject(3, checkIn);
    37	            try (ResultSet rows = statement.executeQuery()) {
    38	                return rows.next();
    39	            }
    40	        }
    41	    }
    42	
    43	    /** Grava a reserva nova e devolve-a já com o id gerado. */
    44	    public Reservation insert(Connection connection, Reservation draft) throws SQLException {
    45	        String sql = "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
    46	                + "guests, rate_plan, company_code, nights, subtotal, discount, status, amount_paid, refund) "
    47	                + "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)";
    48	        try (PreparedStatement statement = connection.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
    49	            int i = 1;
    50	            statement.setInt(i++, draft.roomNumber());
    51	            statement.setString(i++, draft.guestName());
    52	            statement.setString(i++, draft.guestEmail());
    53	            statement.setString(i++, draft.guestCpf());
    54	            statement.setObject(i++, draft.checkIn());
    55	            statement.setObject(i++, draft.checkOut());
    56	            statement.setInt(i++, draft.guests());
    57	            statement.setString(i++, draft.ratePlan());
    58	            statement.setString(i++, draft.companyCode());
    59	            statement.setInt(i++, draft.nights());
    60	            statement.setBigDecimal(i++, draft.subtotal());
    61	            statement.setBigDecimal(i++, draft.discount());
    62	            statement.setString(i++, draft.status().name());
    63	            statement.setBigDecimal(i++, draft.amountPaid());
    64	            statement.setBigDecimal(i, draft.refund());
    65	            statement.executeUpdate();
    66	            try (ResultSet keys = statement.getGeneratedKeys()) {
    67	                keys.next();
    68	                return find(connection, keys.getLong("id"), false).orElseThrow();
    69	            }
    70	        }
    71	    }
    72	
    73	    public void update(Connection connection, Reservation reservation) throws SQLException {
    74	        String sql = "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?";
    75	        try (PreparedStatement statement = connection.prepareStatement(sql)) {
    76	            statement.setString(1, reservation.status().name());
    77	            statement.setBigDecimal(2, reservation.amountPaid());
    78	            statement.setBigDecimal(3, reservation.refund());
    79	            statement.setLong(4, reservation.id());
    80	            statement.executeUpdate();
    81	        }
    82	    }
    83	
    84	    public Optional<Reservation> find(Connection connection, long id, boolean forUpdate) throws SQLException {
    85	        String sql = "SELECT " + COLUMNS + " FROM reservations WHERE id = ?" + (forUpdate ? " FOR UPDATE" : "");
    86	        return queryList(connection, sql, id).stream().findFirst();
    87	    }
    88	
    89	    /** Reservas pagas e não canceladas que ocupam o quarto na noite, por número de quarto. */
    90	    public List<Reservation> findPaidOccupying(Connection connection, LocalDate night) throws SQLException {
    91	        String sql = "SELECT " + COLUMNS + " FROM reservations WHERE status IN ('CONFIRMED','CHECKED_IN','CHECKED_OUT') "
    92	                + "AND check_in <= ? AND check_out > ? ORDER BY room_number, id";
    93	        return queryList(connection, sql, night, night);
    94	    }
    95	
    96	    /** Reservas que deixaram dinheiro com a pousada e começam no período [from, to). */
    97	    public List<Reservation> findWithRevenueStartingBetween(Connection connection, LocalDate from, LocalDate to)
    98	            throws SQLException {
    99	        String sql = "SELECT " + COLUMNS + " FROM reservations WHERE check_in >= ? AND check_in < ? "
   100	                + "AND amount_paid - COALESCE(refund, 0) > 0 ORDER BY check_in, id";
   101	        return queryList(connection, sql, from, to);
   102	    }
   103	
   104	    private List<Reservation> queryList(Connection connection, String sql, Object... params) throws SQLException {
   105	        try (PreparedStatement statement = connection.prepareStatement(sql)) {
   106	            for (int i = 0; i < params.length; i++) {
   107	                statement.setObject(i + 1, params[i]);
   108	            }
   109	            try (ResultSet rows = statement.executeQuery()) {
   110	                List<Reservation> result = new ArrayList<>();
   111	                while (rows.next()) {
   112	                    result.add(map(rows));
   113	                }
   114	                return result;
   115	            }
   116	        }
   117	    }
   118	
   119	    private Reservation map(ResultSet row) throws SQLException {
   120	        BigDecimal refund = row.getBigDecimal("refund");
   121	        return new Reservation(row.getLong("id"), row.getInt("room_number"), row.getString("guest_name"),
   122	                row.getString("guest_email"), row.getString("guest_cpf"), row.getObject("check_in", LocalDate.class),
   123	                row.getObject("check_out", LocalDate.class), row.getInt("guests"), row.getString("rate_plan"),
   124	                row.getString("company_code"), row.getInt("nights"), row.getBigDecimal("subtotal"),
   125	                row.getBigDecimal("discount"), ReservationStatus.valueOf(row.getString("status")),
   126	                row.getBigDecimal("amount_paid"), refund);
   127	    }
